  const $ = (s, r=document) => r.querySelector(s), $$ = (s,r=document) => [...r.querySelectorAll(s)];
  const KEY='sparta-heir-v1';
  const fresh=()=>({resources:{wood:460,stone:360,food:520,iron:185},buildings:{palace:2,quarry:1,farms:1,lumber:1,barracks:1,academy:1},units:{hoplite:24,archer:12,cavalry:5},hero:{level:1,xp:20},tech:{},quests:{build:false,train:false,win:false},view:'city',last:Date.now(),battle:null,zoom:1,muted:false});
  let state; try{state={...fresh(),...JSON.parse(localStorage.getItem(KEY)||'{}')};state.resources={...fresh().resources,...(state.resources||{})};state.buildings={...fresh().buildings,...(state.buildings||{})};state.units={...fresh().units,...(state.units||{})};state.hero={...fresh().hero,...(state.hero||{})};state.quests={...fresh().quests,...(state.quests||{})};state.tech=state.tech||{}}catch{state=fresh()}
  const defs={wood:{label:'Bois',icon:'♣',rate:14},stone:{label:'Pierre',icon:'◈',rate:10},food:{label:'Nourriture',icon:'❖',rate:18},iron:{label:'Fer',icon:'⬟',rate:5}};
  const buildingDefs={quarry:{name:'Carrière',icon:'◈',desc:'Extrait la pierre des collines',cost:{wood:85,stone:45},rate:'+6 pierre / min'},farms:{name:'Fermes',icon:'❖',desc:'Nourrit les citoyens et les troupes',cost:{wood:90,stone:30},rate:'+10 nourriture / min'},lumber:{name:'Camp de bûcherons',icon:'♣',desc:'Fournit du bois de construction',cost:{wood:55,stone:35},rate:'+8 bois / min'},barracks:{name:'Caserne',icon:'⚔',desc:'Entraîne les guerriers de Sparte',cost:{wood:110,stone:90,food:55},rate:'Capacité : 200 soldats'},academy:{name:'Académie',icon:'✧',desc:'Percez les secrets de la guerre',cost:{wood:100,stone:100,iron:35},rate:'Recherche stratégique'}};
  const unitDefs={hoplite:{name:'Hoplites',icon:'⚔',desc:'Infanterie lourde · solide et disciplinée',cost:{food:28,iron:8},power:12},archer:{name:'Archers',icon:'➶',desc:'Tireurs · frappent avant le corps-à-corps',cost:{food:22,wood:12},power:9},cavalry:{name:'Cavalerie',icon:'♞',desc:'Éclaireurs montés · rapides et redoutables',cost:{food:42,iron:19},power:19}};
  const techDefs=[{id:'phalanx',name:'Formation en phalange',desc:'La discipline spartiate renforce les hoplites.',cost:{wood:130,iron:75},bonus:'+15% puissance d’infanterie'},{id:'irrigation',name:'Canaux d’irrigation',desc:'Des récoltes abondantes dans la vallée.',cost:{stone:150,wood:100},bonus:'+20% production de nourriture'},{id:'metalwork',name:'Métallurgie du Péloponnèse',desc:'Des lames de bronze trempé.',cost:{stone:120,iron:100},bonus:'+10% puissance de l’armée'}];
  const nodes=[{id:'athens',x:.18,y:.24,name:'Athènes',type:'Royaume rival',power:42,icon:'⚑'},{id:'temple',x:.77,y:.25,name:'Temple de Poséidon',type:'Site sacré',power:58,icon:'♜'},{id:'olympus',x:.83,y:.64,name:'Colline de l’Olympe',type:'Objectif légendaire',power:88,icon:'♜'},{id:'village',x:.22,y:.69,name:'Village de Sellasie',type:'Camp de pillards',power:26,icon:'⚑'}];
  const save=()=>{state.last=Date.now();localStorage.setItem(KEY,JSON.stringify(state))};
  const fmt=n=>Math.floor(n).toLocaleString('fr-FR');
  function resourceHTML(){return Object.entries(defs).map(([k,d])=>`<div class="resource"><span class="resource-icon">${d.icon}</span><div><b>${fmt(state.resources[k])}</b><small>${d.label} · +${rate(k)}/min</small></div></div>`).join('')}
  function rate(k){let base={...defs[k]};let building={wood:'lumber',stone:'quarry',food:'farms'}[k];let amount=base.rate*(1+Math.max(0,(state.buildings[building]||0)-1)*.65);if(k==='food'&&state.tech.irrigation)amount*=1.2;return Math.round(amount)}
  function totalArmy(){return Object.values(state.units).reduce((a,b)=>a+b,0)}
  function power(){let p=0;Object.entries(state.units).forEach(([k,n])=>p+=n*unitDefs[k].power);if(state.tech.phalanx)p*=1.15;if(state.tech.metalwork)p*=1.1;return Math.round(p*(1+state.hero.level*.025))}
  function costsText(cost){return Object.entries(cost).map(([k,v])=>`${defs[k].icon} ${v}`).join('　')}
  function canPay(cost){return Object.entries(cost).every(([k,v])=>(state.resources[k]||0)>=v)}
  function pay(cost){Object.entries(cost).forEach(([k,v])=>state.resources[k]-=v)}
  function toast(title,text){const el=document.createElement('div');el.className='toast';el.innerHTML=`<b>${title}</b>${text}`;$('#toastStack').append(el);setTimeout(()=>el.remove(),3600)}
  function log(text){$('#activityText').textContent=text;$('#clock').textContent='À L’INSTANT'}
  function updateHeader(){ $('#resources').innerHTML=resourceHTML();$('#heroLevel').textContent=state.hero.level;$('#armyBadge').textContent=totalArmy();$('#battleBanner').classList.toggle('hidden',!state.battle);if(state.battle)$('#battleText').textContent=`${state.battle.name} · ${Math.max(1,Math.ceil(state.battle.time))} s`; }
  function levelUp(){let needed=state.hero.level*100;if(state.hero.xp>=needed){state.hero.xp-=needed;state.hero.level++;toast('DILIOS S’ÉLÈVE',`Niveau ${state.hero.level} atteint · +15 puissance`);log(`Dilios atteint le niveau ${state.hero.level}.`)}}
  function tick(){const now=Date.now();let delta=Math.min(60,(now-(state.last||now))/1000);state.last=now;for(const k of Object.keys(defs))state.resources[k]+=rate(k)*delta/60;state.resources.food=Math.max(0,state.resources.food-totalArmy()*.008*delta);if(state.battle){state.battle.time-=delta;state.battle.enemy=Math.max(0,state.battle.enemy-(power()/Math.max(1,state.battle.maxPower))*delta*4);if(state.battle.time<=0||state.battle.enemy<=0)endBattle(state.battle.enemy<=0)}updateHeader();save()}
  function startBattle(node){if(state.battle)return;if(totalArmy()<5){toast('ARMÉE INSUFFISANTE','Entraînez au moins 5 soldats avant de partir en campagne.');return}if(state.units.hoplite+state.units.archer+state.units.cavalry<node.power*.28){toast('ENNEMI REDOUTABLE',`Recrutez davantage de soldats avant d’attaquer ${node.name}.`);return}state.battle={id:node.id,name:node.name,time:Math.max(8,20-node.power/8),enemy:node.power,maxPower:node.power,initial:node.power};state.view='world';setNav('world');renderPanel();setMode('world');$('#battleBanner').classList.remove('hidden');$('#mapEvent').classList.add('hidden');log(`La phalange de Dilios marche sur ${node.name}.`);toast('EN AVANT, SPARTIATES !',`${node.name} · La bataille commence sur la carte.`);draw()}
  function endBattle(won){let b=state.battle;if(!b)return;state.battle=null;$('#battleBanner').classList.add('hidden');$('#mapEvent').classList.remove('hidden');if(won){const loot=Math.round(b.initial*3+80);state.resources.wood+=loot;state.resources.stone+=Math.round(loot*.6);state.resources.food+=Math.round(loot*.7);state.hero.xp+=45+Math.round(b.initial/2);state.quests.win=true;levelUp();toast('VICTOIRE SPARTIATE',`${b.name} est à vous. Butin : ${loot} bois, ${Math.round(loot*.6)} pierre.`);log(`Victoire à ${b.name} : la gloire et le butin reviennent à Sparte.`)}else{state.units.hoplite=Math.max(0,state.units.hoplite-Math.ceil(state.units.hoplite*.22));state.units.archer=Math.max(0,state.units.archer-Math.ceil(state.units.archer*.18));state.units.cavalry=Math.max(0,state.units.cavalry-Math.ceil(state.units.cavalry*.25));toast('RETRAITE',`La phalange se replie de ${b.name}. Renforcez vos rangs.`);log(`La bataille de ${b.name} s’achève par une retraite.`)}updateHeader();renderPanel();draw();save()}
  function openModal(title,kicker,description,choices){const m=$('#modal');m.innerHTML=`<button class="modal-close" aria-label="Fermer">×</button><div class="modal-kicker">${kicker}</div><h2>${title}</h2><p>${description}</p><div class="choice-list">${choices}</div>`;$('#modalBackdrop').classList.remove('hidden');$('.modal-close',m).onclick=closeModal;$('#modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')closeModal()};$$('.choice',m).forEach(el=>el.onclick=()=>{const fn=el.dataset.action;if(fn&&actions[fn])actions[fn](el.dataset.id);closeModal()})}
  function closeModal(){$('#modalBackdrop').classList.add('hidden')}
  function choicesForBuildings(){return Object.entries(buildingDefs).map(([id,b])=>`<button class="choice" data-action="build" data-id="${id}"><span class="choice-icon">${b.icon}</span><span><b>${b.name}</b><small>${b.desc} · ${b.rate}</small></span><em>${costsText(b.cost)}</em></button>`).join('')}
  function actionsForUnits(){return Object.entries(unitDefs).map(([id,u])=>`<button class="choice" data-action="train" data-id="${id}"><span class="choice-icon">${u.icon}</span><span><b>${u.name}</b><small>${u.desc} · Puissance ${u.power}</small></span><em>${costsText(u.cost)}</em></button>`).join('')}
  const actions={build(id){let b=buildingDefs[id];if(!canPay(b.cost)){toast('RESSOURCES INSUFFISANTES',`Il vous faut ${costsText(b.cost)}.`);return}pay(b.cost);state.buildings[id]=(state.buildings[id]||0)+1;state.quests.build=true;state.hero.xp+=12;levelUp();log(`${b.name} amélioré au niveau ${state.buildings[id]}.`);toast('CHANTIER ACHEVÉ',`${b.name} atteint le niveau ${state.buildings[id]}.`);renderAll();draw();save()},train(id){let u=unitDefs[id],n=5,cost=Object.fromEntries(Object.entries(u.cost).map(([k,v])=>[k,v*n]));if(!canPay(cost)){toast('RESSOURCES INSUFFISANTES',`Pour 5 soldats : ${costsText(cost)}.`);return}pay(cost);state.units[id]+=n;state.quests.train=true;log(`${n} ${u.name.toLowerCase()} rejoignent la phalange.`);toast('NOUVELLES RECRUES',`${n} ${u.name.toLowerCase()} prêts au combat.`);renderAll();save()},research(id){let t=techDefs.find(x=>x.id===id);if(!t||state.tech[id])return;if(!canPay(t.cost)){toast('RESSOURCES INSUFFISANTES',`Recherche : ${costsText(t.cost)}.`);return}pay(t.cost);state.tech[id]=true;state.hero.xp+=20;levelUp();toast('SAVOIR ANCESTRAL',`${t.name} · ${t.bonus}`);log(`La recherche « ${t.name} » est achevée.`);renderAll();draw();save()},attack(id){let node=nodes.find(x=>x.id===id);if(node)startBattle(node)}};
  function setNav(view){state.view=view;$$('.nav-item,.mobile-nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===view));$('#pageTitle').textContent={city:'La cité des rois',world:'Le monde hellénique',army:'La phalange de Sparte',research:'Savoir et stratégie',alliance:'Le conseil des alliés'}[view]||'La cité des rois';$('#eyebrow').textContent={city:'PÉLOPONNÈSE · CŒUR DE LA LAKÔNIE',world:'MER ÉGÉE · ROYAUMES ET CONQUÊTES',army:'CASERNE ROYALE · FORCES DE SPARTE',research:'ACADÉMIE · SAGESSE DES ANCIENS',alliance:'CONSEIL · FRÈRES D’ARMES'}[view]||'';if(view==='world')setMode('world');else if(view==='city')setMode('city');renderPanel();if(innerWidth<=700&&['army','research','alliance'].includes(view))$('#rightPanel')?.classList.add('open');draw();save()}
  function setMode(mode){$$('.map-control').forEach(x=>x.classList.toggle('selected',x.dataset.mode===mode));canvasMode=mode;draw()}
  let panelTab='overview';
  function renderPanel(){const c=$('#panelContent');if(panelTab==='hero'){c.innerHTML=heroPanel();return}if(panelTab==='tasks'){c.innerHTML=tasksPanel();return}if(state.view==='army'){c.innerHTML=armyPanel();return}if(state.view==='research'){c.innerHTML=researchPanel();return}if(state.view==='alliance'){c.innerHTML=alliancePanel();return}c.innerHTML=cityPanel();}
  function cityPanel(){let names={quarry:'Carrière',farms:'Fermes',lumber:'Bûcherons',barracks:'Caserne',academy:'Académie'};return `<div class="section-head"><h2>Foyer spartiate</h2><button data-open="build">＋ CONSTRUIRE</button></div><div class="city-card"><span class="city-level">CITADELLE · NIVEAU ${state.buildings.palace}</span><h3>Lacédémone</h3><p>Le cœur de la puissance spartiate</p><div class="city-bottom"><span>Population <b>${(totalArmy()*12+680).toLocaleString('fr-FR')}</b></span><span>Puissance <b>⚔ ${fmt(power())}</b></span></div></div><div class="panel-subhead">BÂTIMENTS DE LA CITÉ</div>${Object.keys(names).map(id=>{let b=buildingDefs[id],lv=state.buildings[id]||0;return `<div class="building-row"><span class="building-icon">${b.icon}</span><span class="building-info"><b>${b.name}</b><small>Niveau ${lv} · ${id==='quarry'?'+6 pierre/min':id==='farms'?'+10 nourriture/min':id==='lumber'?'+8 bois/min':b.rate}</small></span><span class="building-level">${lv}</span><button data-upgrade="${id}">AMÉLIORER</button></div>`}).join('')}<div class="panel-actions"><button class="action-btn primary" data-open="train">⚔ ENTRAÎNER</button><button class="action-btn" data-open="build">＋ BÂTIR</button></div><div class="production-note"><span>PRODUCTION TOTALE</span><b>✦ Ressources en hausse</b></div>`}
  function heroPanel(){return `<div class="section-head"><h2>Votre champion</h2><button id="heroTrain">ENTRAÎNER</button></div><div class="hero-card"><div class="hero-portrait">D</div><div class="hero-meta"><h3>Dilios de Sparte</h3><p>LE CONTEUR · NIVEAU ${state.hero.level}</p><div class="xp-bar"><i style="width:${Math.min(100,state.hero.xp/(state.hero.level*100)*100)}%"></i></div><small style="font-size:7px;color:#96978e">${state.hero.xp} / ${state.hero.level*100} XP</small></div></div><div class="stat-grid"><div class="stat"><b>${power()}</b><small>PUISSANCE</small></div><div class="stat"><b>${totalArmy()}</b><small>GUERRIERS</small></div><div class="stat"><b>+${state.hero.level*2}%</b><small>ATTAQUE</small></div></div><div class="panel-subhead">APTITUDES DU HÉROS</div><div class="quest-item"><span class="quest-check">⚔</span><div><b>Discours de guerre</b><small>La phalange combat avec l’ardeur de trois cents.</small><div class="quest-reward">+${state.hero.level*2}% puissance d’armée</div></div></div><div class="quest-item"><span class="quest-check">♜</span><div><b>Conquérant</b><small>Chaque victoire forge la légende de Dilios.</small><div class="quest-reward">Butin de campagne augmenté</div></div></div><button class="action-btn primary" style="width:100%;margin-top:13px" data-open="train">RECRUTER DES SOLDATS</button>`}
  function tasksPanel(){return `<div class="section-head"><h2>Chroniques de Sparte</h2><button>JOUR 1 / 7</button></div><div class="panel-subhead">QUÊTES DU STRATÈGE</div>${[[state.quests.build,'Fortifier la cité','Améliorez un bâtiment de votre cité.','✦ +50 bois · 20 XP'],[state.quests.train,'Forger la phalange','Entraînez vos premiers guerriers spartiates.','⚔ +5 hoplites · 20 XP'],[state.quests.win,'Première conquête','Remportez une bataille sur la carte du monde.','♜ +120 de chaque ressource']].map(([done,title,desc,reward])=>`<div class="quest-item"><span class="quest-check">${done?'✓':'◇'}</span><div><b>${title}</b><small>${desc}</small><div class="quest-reward">${done?'ACCOMPLIE · ':''}${reward}</div></div></div>`).join('')}<div class="panel-subhead">SAGA DE LAKÔNIE</div><div class="quest-item"><span class="quest-check">I</span><div><b>Les ombres d’Athènes</b><small>Un rival rassemble ses troupes au nord. Préparez votre première marche.</small><div class="quest-reward">PROGRESSION · ${state.quests.win?'1':'0'} / 1</div></div></div>`}
  function armyPanel(){return `<div class="section-head"><h2>Ordre de bataille</h2><button data-open="train">＋ RECRUTER</button></div><div class="city-card" style="height:94px"><span class="city-level">GARDE ROYALE · DILIOS</span><h3>${fmt(power())} de puissance</h3><p>${totalArmy()} soldats prêts à servir Sparte</p><div class="city-bottom"><span>Moral <b>Excellent</b></span><span>Capacité <b>${totalArmy()} / 200</b></span></div></div><div class="panel-subhead">UNITÉS DISPONIBLES</div>${Object.entries(unitDefs).map(([id,u])=>`<div class="unit-card"><span class="unit-symbol">${u.icon}</span><span class="unit-details"><b>${u.name}</b><small>${u.desc}</small></span><span class="unit-count">${state.units[id]}</span><button data-train="${id}">+5</button></div>`).join('')}<div class="panel-actions"><button class="action-btn primary" data-open="train">ENTRAÎNER</button><button class="action-btn" data-view="world">MARCHER ↗</button></div><div class="production-note"><span>PUISSANCE DE COMBAT</span><b>⚔ ${power()} · ${totalArmy()} soldats</b></div>`}
  function researchPanel(){return `<div class="section-head"><h2>Académie royale</h2><span style="font-size:8px;color:#999">SAVOIR ANCIEN</span></div><div class="city-card" style="height:91px"><span class="city-level">ÉRUDITION · NIVEAU ${state.buildings.academy}</span><h3>La sagesse est une arme</h3><p>Choisissez les découvertes de Sparte.</p></div><div class="panel-subhead">RECHERCHES DISPONIBLES</div>${techDefs.map(t=>`<div class="tech-item"><div class="tech-head"><b>${t.name}</b><span>${state.tech[t.id]?'✓ ACQUIS':''}</span></div><p>${t.desc} <b style="color:#c3ab73">${t.bonus}</b></p><button data-research="${t.id}" ${state.tech[t.id]?'disabled':''}>${state.tech[t.id]?'RECHERCHE TERMINÉE':'DÉCOUVRIR · '+costsText(t.cost)}</button></div>`).join('')}`}
  function alliancePanel(){return `<div class="section-head"><h2>Votre alliance</h2><button>CLASSEMENT ↗</button></div><div class="alliance-banner"><small>♜ ALLIANCE · TOP 12 DU ROYAUME</small><h3>LES LIONS DE LAKÔNIE</h3><p>Unis dans l’honneur, invincibles dans la bataille.</p></div><div class="stat-grid"><div class="stat"><b>12</b><small>MEMBRES</small></div><div class="stat"><b>8.4k</b><small>PUISSANCE</small></div><div class="stat"><b>#08</b><small>RANG</small></div></div><div class="panel-subhead">FRÈRES D’ARMES · EN LIGNE</div>${[['L','Leonidas_300','Maréchal · 2 min'],['A','Aristôn','Vétéran · 5 min'],['M','Myrrine','Éclaireuse · 12 min'],['T','Theron','Stratège · 18 min']].map(x=>`<div class="member-row"><span class="member-avatar">${x[0]}</span><b>${x[1]}</b><span class="online-dot tiny"></span><small>${x[2]}</small></div>`).join('')}<button class="action-btn primary" style="width:100%;margin-top:15px" id="donateBtn">OFFRIR DES RESSOURCES · ALLIANCE</button><p style="font-size:8px;color:#999">Le Temple de Poséidon sera bientôt disputé. Une alliance unie peut revendiquer les lieux sacrés.</p>`}
  // Canvas artwork: hand-painted, isometric Greek valley and its miniature city.
  const canvas=$('#worldCanvas'),ctx=canvas.getContext('2d');let canvasMode='city',size={w:800,h:500},cam={x:0,y:0};let seed=173;
  function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}
  function resize(){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);size={w:r.width,h:r.height};canvas.width=r.width*d;canvas.height=r.height*d;ctx.setTransform(d,0,0,d,0,0);draw()}
  function path(points,fill,stroke){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
  function ellipse(x,y,rx,ry,fill){ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fillStyle=fill;ctx.fill()}
  function iso(x,y,z=0){let s=Math.min(size.w/850,size.h/480)*state.zoom;return [size.w*.5+(x-y)*.72*s+cam.x,size.h*.46+(x+y)*.34*s-z*s+cam.y]}
  function tile(x,y,z,color){let p=iso(x,y,z),s=Math.min(size.w/850,size.h/480)*state.zoom;path([[p[0],p[1]],[p[0]+34*s,p[1]+16*s],[p[0],p[1]+32*s],[p[0]-34*s,p[1]+16*s]],color)}
